package com.hbm.items.registry;

import java.util.ArrayList;
import java.util.List;

import com.hbm.inventory.material.Mats;
import com.hbm.inventory.material.MaterialShapes;
import com.hbm.items.ModItems;
import com.hbm.items.special.ItemAutogen;
import com.hbm.registry.HbmRegistry;
import com.hbm.registry.IRegistrar;

import net.minecraft.item.Item;

/**
 * The registration unit for the "autogenerated material subtypes" family: ingots/dusts/plates/wires/pipes/parts, the raw-material items.
 *
 * Each meta maps to one material (meta is the material id); textures are remapped by material color at load,
 * with per-meta model JSONs generated by `tools/gen_autogen_models.py` (225 of them).
 * Sprite manufacturing lives in {@link com.hbm.items.special.ItemAutogenSprites}.
 */
public class ItemsAutogen implements IRegistrar {

	private final List<Item> created = new ArrayList<>();

	@Override
	public String id() {
		return "items.autogen";
	}

	@Override
	public void preInit() {

		created.add(ModItems.bolt = HbmRegistry.item(new ItemAutogen(MaterialShapes.BOLT).oun("boltntm").setUnlocalizedName("bolt").setCreativeTab(ModItems.partsTab), "bolt"));

		created.add(ModItems.bedrock_ore_fragment = HbmRegistry.item(new ItemAutogen(MaterialShapes.FRAGMENT).aot(Mats.MAT_BISMUTH, "bedrock_ore_fragment_bismuth").setUnlocalizedName("bedrock_ore_fragment").setCreativeTab(ModItems.partsTab), "bedrock_ore_fragment"));

		created.add(ModItems.shell = HbmRegistry.item(new ItemAutogen(MaterialShapes.SHELL).oun("shellntm").setUnlocalizedName("shell").setCreativeTab(ModItems.partsTab), "shell"));

		created.add(ModItems.pipe = HbmRegistry.item(new ItemAutogen(MaterialShapes.PIPE).oun("pipentm").setUnlocalizedName("pipe").setCreativeTab(ModItems.partsTab), "pipe"));

		created.add(ModItems.ingot_raw = HbmRegistry.item(new ItemAutogen(MaterialShapes.INGOT).setUnlocalizedName("ingot_raw").setCreativeTab(ModItems.partsTab), "ingot_raw"));

		created.add(ModItems.plate_cast = HbmRegistry.item(new ItemAutogen(MaterialShapes.CASTPLATE).aot(Mats.MAT_BISMUTH, "plate_cast_bismuth").setUnlocalizedName("plate_cast").setCreativeTab(ModItems.partsTab), "plate_cast"));

		created.add(ModItems.plate_welded = HbmRegistry.item(new ItemAutogen(MaterialShapes.WELDEDPLATE).setUnlocalizedName("plate_welded").setCreativeTab(ModItems.partsTab), "plate_welded"));

		created.add(ModItems.wire_fine = HbmRegistry.item(new ItemAutogen(MaterialShapes.WIRE)
				.aot(Mats.MAT_ALUMINIUM, "wire_aluminium").aot(Mats.MAT_COPPER, "wire_copper")
				.aot(Mats.MAT_MINGRADE, "wire_red_copper").aot(Mats.MAT_GOLD, "wire_gold")
				.aot(Mats.MAT_TUNGSTEN, "wire_tungsten").aot(Mats.MAT_CARBON, "wire_carbon")
				.aot(Mats.MAT_SCHRABIDIUM, "wire_schrabidium").aot(Mats.MAT_MAGTUNG, "wire_magnetized_tungsten")
				.aot(Mats.MAT_ZINC, "wire_zinc")
				.setUnlocalizedName("wire_fine").setCreativeTab(ModItems.partsTab), "wire_fine"));

		created.add(ModItems.wire_dense = HbmRegistry.item(new ItemAutogen(MaterialShapes.DENSEWIRE).setUnlocalizedName("wire_dense").setCreativeTab(ModItems.partsTab), "wire_dense"));

		created.add(ModItems.part_barrel_light = HbmRegistry.item(new ItemAutogen(MaterialShapes.LIGHTBARREL).setUnlocalizedName("part_barrel_light").setCreativeTab(ModItems.partsTab), "part_barrel_light"));
		created.add(ModItems.part_barrel_heavy = HbmRegistry.item(new ItemAutogen(MaterialShapes.HEAVYBARREL).setUnlocalizedName("part_barrel_heavy").setCreativeTab(ModItems.partsTab), "part_barrel_heavy"));
		created.add(ModItems.part_receiver_light = HbmRegistry.item(new ItemAutogen(MaterialShapes.LIGHTRECEIVER).setUnlocalizedName("part_receiver_light").setCreativeTab(ModItems.partsTab), "part_receiver_light"));
		created.add(ModItems.part_receiver_heavy = HbmRegistry.item(new ItemAutogen(MaterialShapes.HEAVYRECEIVER).setUnlocalizedName("part_receiver_heavy").setCreativeTab(ModItems.partsTab), "part_receiver_heavy"));
		created.add(ModItems.part_mechanism = HbmRegistry.item(new ItemAutogen(MaterialShapes.MECHANISM).setUnlocalizedName("part_mechanism").setCreativeTab(ModItems.partsTab), "part_mechanism"));
		created.add(ModItems.part_stock = HbmRegistry.item(new ItemAutogen(MaterialShapes.STOCK).setUnlocalizedName("part_stock").setCreativeTab(ModItems.partsTab), "part_stock"));
		created.add(ModItems.part_grip = HbmRegistry.item(new ItemAutogen(MaterialShapes.GRIP).setUnlocalizedName("part_grip").setCreativeTab(ModItems.partsTab), "part_grip"));
	}

	@Override
	public void registerModels() {
		for(Item item : created) ItemModels.registerAll(item);
	}
}
